_PAIRS = [a + b for a in "ABCD" for b in "ABCD"]

@st.composite
def gen(draw):
    names = draw(st.lists(st.sampled_from(_PAIRS), min_size=1, max_size=6, unique=True))
    return f"{len(names)}\n" + "\n".join(names) + "\n"

def validate(inp):
    lines = inp.split("\n")
    if not lines or lines[-1] != "":
        return False
    lines = lines[:-1]
    if len(lines) < 1:
        return False
    try:
        n = int(lines[0])
    except ValueError:
        return False
    if not (1 <= n <= 26 * 26):
        return False
    if len(lines) != n + 1:
        return False
    names = lines[1:]
    for s in names:
        if len(s) != 2 or not all("A" <= c <= "Z" for c in s):
            return False
    return len(set(names)) == n

def ref(inp):
    # Brute force model:
    # Each NG string is a walk in the directed graph whose edges are the used names
    # (consecutive letters of the string form used names). A walk covers the set of
    # edges it traverses. We enumerate ALL reachable (last vertex, covered-edge-set)
    # states by BFS over walks (finite state space), then find the minimum number
    # of walks whose covered sets union to all edges.
    t = inp.split()
    n = int(t[0])
    E = t[1:1 + n]
    full = (1 << n) - 1
    seen = set()
    stack = []
    for i, e in enumerate(E):
        st0 = (e[1], 1 << i)
        if st0 not in seen:
            seen.add(st0)
            stack.append(st0)
    while stack:
        v, m = stack.pop()
        for j, f in enumerate(E):
            if f[0] == v:
                ns = (f[1], m | (1 << j))
                if ns not in seen:
                    seen.add(ns)
                    stack.append(ns)
    masks = set(m for _, m in seen)
    # keep only maximal masks (a walk covering a subset is never needed)
    maximal = [m for m in masks if not any(o != m and (o & m) == m for o in masks)]
    k = 1
    while True:
        for combo in combinations(maximal, k):
            acc = 0
            for m in combo:
                acc |= m
            if acc == full:
                return str(k)
        k += 1
