import itertools
from hypothesis import strategies as st


@st.composite
def gen(draw):
    # Small N so that the bounded multiplicity search in ref stays fast.
    n = draw(st.integers(1, 5))
    alphabet = "ABCD"
    pairs = [a + b for a in alphabet for b in alphabet]
    names = draw(st.lists(st.sampled_from(pairs), min_size=n, max_size=n, unique=True))
    return f"{n}\n" + "".join(s + "\n" for s in names)


def validate(inp):
    t = inp.split()
    if not t:
        return False
    try:
        n = int(t[0])
    except ValueError:
        return False
    if not (1 <= n <= 26 * 26):
        return False
    names = t[1:]
    if len(names) != n:
        return False
    for s in names:
        if len(s) != 2 or not all("A" <= ch <= "Z" for ch in s):
            return False
    if len(set(names)) != n:
        return False
    return True


def ref(inp):
    # Model: vertices are the 26 letters, each used name XY is a directed edge X->Y.
    # An NG string is a walk; the NG list is a family of walks covering every edge
    # (a walk may reuse edges, so an edge may be traversed several times).
    #
    # Reasoning used:
    #  - Choose traversal multiplicity m_e >= 1 for each edge e (how many times the
    #    walks in total traverse it). The multigraph with these multiplicities must be
    #    split exactly into walks, and conversely any covering gives such a multigraph.
    #  - Standard fact: a weakly connected directed multigraph whose edges can be
    #    split into trails needs exactly max(1, sum over vertices of max(0, out-in))
    #    trails. Components are independent since a walk stays in one component.
    #  - So the answer is the minimum over multiplicity choices of the sum over
    #    components of max(1, positive excess of that component).
    #  - Multiplicities are searched over {1, 2}, which suffices for the small inputs
    #    this spec generates (the samples need at most multiplicity 2).
    t = inp.split()
    n = int(t[0])
    E = t[1:1 + n]
    letters = sorted(set("".join(E)))
    best = None
    for mult in itertools.product((1, 2), repeat=n):
        out = {c: 0 for c in letters}
        inn = {c: 0 for c in letters}
        parent = {c: c for c in letters}

        def find(x):
            while parent[x] != x:
                x = parent[x]
            return x

        for s, m in zip(E, mult):
            a, b = s[0], s[1]
            out[a] += m
            inn[b] += m
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
        pos = {}
        for c in letters:
            r = find(c)
            pos[r] = pos.get(r, 0) + max(0, out[c] - inn[c])
        total = sum(max(1, p) for p in pos.values())
        if best is None or total < best:
            best = total
    return str(best)
