import itertools
from hypothesis import strategies as st

_PAIRS = [a + b for a in "ABCDE" for b in "ABCDE"]


@st.composite
def gen(draw):
    n = draw(st.integers(1, 6))
    names = draw(st.lists(st.sampled_from(_PAIRS), min_size=n, max_size=n, unique=True))
    return f"{n}\n" + "\n".join(names) + "\n"


def validate(inp):
    lines = inp.split("\n")
    # tolerate trailing newline(s)
    toks = inp.split()
    if not toks:
        return False
    try:
        n = int(toks[0])
    except ValueError:
        return False
    names = toks[1:]
    if not (1 <= n <= 26 * 26):
        return False
    if len(names) != n:
        return False
    for s in names:
        if len(s) != 2 or not all("A" <= c <= "Z" for c in s):
            return False
    if len(set(names)) != n:
        return False
    return True


def ref(inp):
    # Model: each NG string is a walk in the directed graph whose vertices are the
    # 26 letters and whose edges are the used names (consecutive letter pairs must
    # be used names). We need walks covering every edge at least once.
    # Brute force over edge multiplicities c in {1,2,3} (extra copies allowed) for
    # each weakly connected component of the original graph. For a connected
    # multigraph, the minimum number of trails decomposing it equals
    # max(1, sum of positive (out-in) imbalances) (1 when balanced: Eulerian circuit).
    toks = inp.split()
    n = int(toks[0])
    names = toks[1:1 + n]

    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    for s in names:
        union(s[0], s[1])

    comps = {}
    for s in names:
        comps.setdefault(find(s[0]), []).append((s[0], s[1]))

    total = 0
    for edges in comps.values():
        best = None
        for mult in itertools.product(range(1, 4), repeat=len(edges)):
            out = {}
            inn = {}
            for (u, v), c in zip(edges, mult):
                out[u] = out.get(u, 0) + c
                inn[v] = inn.get(v, 0) + c
            pos = 0
            for x in set(out) | set(inn):
                d = out.get(x, 0) - inn.get(x, 0)
                if d > 0:
                    pos += d
            val = max(pos, 1)
            if best is None or val < best:
                best = val
        total += best
    return str(total)


